/*
 * Hand-written replacement for the obsconfig.h normally generated by CMake.
 *
 * libobs/obs-config.h includes "obsconfig.h" unconditionally, so an OBS plugin
 * built outside the OBS build system must provide this file.
 *
 * The values below match an installed Windows OBS build; none of them is used
 * by the code we compile (libobs resolves its own paths internally), they only
 * need to exist with a sane shape.
 */
#pragma once

#define OBS_DATA_PATH "data"
#define OBS_PLUGIN_PATH "obs-plugins/64bit"
#define OBS_PLUGIN_DESTINATION "obs-plugins/64bit"

#define OBS_RELEASE_CANDIDATE 0
#define OBS_BETA 0
